create schema if not exists tech;
revoke all on schema tech from anon, authenticated;
grant usage on schema tech to service_role;

create table tech.clients (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),portal_user_id uuid references vgroup.users(id) on delete set null,company_name text not null,contact_name text,email text,phone text,status text not null default 'active' check (status in ('lead','active','paused','completed','archived')),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_unit_id,email));
create table tech.projects (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),client_id uuid not null references tech.clients(id),project_manager_id uuid references vgroup.users(id),name text not null,description text,project_type text not null default 'custom' check (project_type in ('custom','website','mobile_app','system','saas_implementation','other')),currency text not null default 'EGP',base_price numeric(18,2) not null default 0 check (base_price>=0),current_price numeric(18,2) not null default 0 check (current_price>=0),progress_percent numeric(5,2) not null default 0 check (progress_percent>=0 and progress_percent<=100),current_phase text,planned_start date,planned_end date,target_end date,actual_end date,status text not null default 'planning' check (status in ('planning','active','on_hold','completed','cancelled','archived')),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check (target_end is null or planned_start is null or target_end>=planned_start));
create table tech.project_team_members (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,user_id uuid not null references vgroup.users(id),role_code text not null,allocation_percent numeric(5,2) not null default 100 check (allocation_percent>0 and allocation_percent<=100),created_at timestamptz not null default now(),unique(project_id,user_id));
create table tech.duration_price_options (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,label text not null,duration_days integer not null check (duration_days>0),total_price numeric(18,2) not null check (total_price>=0),is_selected boolean not null default false,valid_until timestamptz,created_at timestamptz not null default now(),unique(project_id,label));
create table tech.project_phases (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,name text not null,sequence integer not null check (sequence>0),planned_start date,planned_end date,actual_start date,actual_end date,weight_percent numeric(5,2) not null default 0 check (weight_percent>=0 and weight_percent<=100),progress_percent numeric(5,2) not null default 0 check (progress_percent>=0 and progress_percent<=100),status text not null default 'planned' check (status in ('planned','active','blocked','completed','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,sequence));
create table tech.scope_items (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,title text not null,description text,category text,status text not null default 'included' check (status in ('included','removed','completed')),sequence integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table tech.change_requests (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,requested_by uuid not null references vgroup.users(id),title text not null,description text not null,status text not null default 'submitted' check (status in ('submitted','priced','approved','rejected','implemented','cancelled')),proposed_price numeric(18,2) check (proposed_price is null or proposed_price>=0),extra_days integer check (extra_days is null or extra_days>=0),priced_by uuid references vgroup.users(id),priced_at timestamptz,decided_by uuid references vgroup.users(id),decided_at timestamptz,decision_note text,implemented_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table tech.checklist_items (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,phase_id uuid references tech.project_phases(id) on delete set null,scope_item_id uuid references tech.scope_items(id) on delete set null,change_request_id uuid references tech.change_requests(id) on delete set null,title text not null,assigned_to uuid references vgroup.users(id),due_at timestamptz,completed_at timestamptz,status text not null default 'todo' check (status in ('todo','in_progress','blocked','review','done','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table tech.project_updates (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,author_id uuid references vgroup.users(id),update_type text not null default 'general',title text not null,body text,visible_to_client boolean not null default true,created_at timestamptz not null default now());
create table tech.project_files (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,uploaded_by uuid references vgroup.users(id),file_name text not null,storage_path text not null unique,mime_type text,size_bytes bigint not null default 0 check (size_bytes>=0),visible_to_client boolean not null default true,created_at timestamptz not null default now());
create table tech.payment_installments (id uuid primary key default gen_random_uuid(),project_id uuid not null references tech.projects(id) on delete cascade,change_request_id uuid references tech.change_requests(id) on delete set null,installment_number integer not null check (installment_number>0),label text,currency text not null default 'EGP',amount numeric(18,2) not null check (amount>=0),due_date date,paid_amount numeric(18,2) not null default 0 check (paid_amount>=0),paid_at timestamptz,status text not null default 'pending' check (status in ('pending','partial','paid','overdue','waived','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,installment_number),check (paid_amount<=amount));
create table tech.subscription_plans (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),code text not null,name text not null,billing_period text not null check (billing_period in ('monthly','yearly')),currency text not null default 'EGP',price numeric(18,2) not null check (price>=0),features jsonb not null default '[]'::jsonb,active boolean not null default true,created_at timestamptz not null default now(),unique(business_unit_id,code,billing_period));
create table tech.subscriptions (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),client_id uuid not null references tech.clients(id),plan_id uuid not null references tech.subscription_plans(id),tenant_key text not null unique,status text not null default 'trialing' check (status in ('trialing','active','past_due','cancelled')),current_period_start timestamptz,current_period_end timestamptz,trial_ends_at timestamptz,cancelled_at timestamptz,external_customer_id text,external_subscription_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table tech.subscription_invoices (id uuid primary key default gen_random_uuid(),subscription_id uuid not null references tech.subscriptions(id) on delete cascade,currency text not null default 'EGP',amount numeric(18,2) not null check (amount>=0),due_at timestamptz,paid_at timestamptz,status text not null default 'pending' check (status in ('pending','paid','past_due','void')),idempotency_key text not null unique,created_at timestamptz not null default now());

create index on tech.clients(business_unit_id,status); create index on tech.clients(portal_user_id); create index on tech.projects(client_id,status); create index on tech.projects(project_manager_id); create index on tech.project_team_members(user_id); create index on tech.project_phases(project_id,status); create index on tech.scope_items(project_id,status); create index on tech.checklist_items(project_id,status); create index on tech.checklist_items(phase_id); create index on tech.checklist_items(scope_item_id); create index on tech.checklist_items(change_request_id); create index on tech.checklist_items(assigned_to); create index on tech.project_updates(project_id,created_at); create index on tech.project_updates(author_id); create index on tech.project_files(project_id,created_at); create index on tech.project_files(uploaded_by); create index on tech.payment_installments(project_id,status,due_date); create index on tech.payment_installments(change_request_id); create index on tech.change_requests(project_id,status); create index on tech.change_requests(requested_by); create index on tech.change_requests(priced_by); create index on tech.change_requests(decided_by); create index on tech.subscription_plans(business_unit_id,active); create index on tech.subscriptions(client_id,status); create index on tech.subscriptions(plan_id); create index on tech.subscription_invoices(subscription_id,status);

alter table tech.clients enable row level security; alter table tech.projects enable row level security; alter table tech.project_team_members enable row level security; alter table tech.duration_price_options enable row level security; alter table tech.project_phases enable row level security; alter table tech.scope_items enable row level security; alter table tech.checklist_items enable row level security; alter table tech.project_updates enable row level security; alter table tech.project_files enable row level security; alter table tech.payment_installments enable row level security; alter table tech.change_requests enable row level security; alter table tech.subscription_plans enable row level security; alter table tech.subscriptions enable row level security; alter table tech.subscription_invoices enable row level security;
revoke all on all tables in schema tech from anon, authenticated; grant all on all tables in schema tech to service_role; grant all on all sequences in schema tech to service_role;
create policy clients_server_only on tech.clients for all to authenticated using(false) with check(false); create policy projects_server_only on tech.projects for all to authenticated using(false) with check(false); create policy project_team_members_server_only on tech.project_team_members for all to authenticated using(false) with check(false); create policy duration_price_options_server_only on tech.duration_price_options for all to authenticated using(false) with check(false); create policy project_phases_server_only on tech.project_phases for all to authenticated using(false) with check(false); create policy scope_items_server_only on tech.scope_items for all to authenticated using(false) with check(false); create policy checklist_items_server_only on tech.checklist_items for all to authenticated using(false) with check(false); create policy project_updates_server_only on tech.project_updates for all to authenticated using(false) with check(false); create policy project_files_server_only on tech.project_files for all to authenticated using(false) with check(false); create policy payment_installments_server_only on tech.payment_installments for all to authenticated using(false) with check(false); create policy change_requests_server_only on tech.change_requests for all to authenticated using(false) with check(false); create policy subscription_plans_server_only on tech.subscription_plans for all to authenticated using(false) with check(false); create policy subscriptions_server_only on tech.subscriptions for all to authenticated using(false) with check(false); create policy subscription_invoices_server_only on tech.subscription_invoices for all to authenticated using(false) with check(false);
